dict(toc='Role of civil services in a democracy', id=4, title='SIX ROLES OF CIVIL SERVANTS IN A DEMOCRACY', part=1, icon='scale', prio='M',
 pyq='Mains 2017 (neutrality and effectiveness) · Handout M1 pp. 9-12',
 simple='A civil servant must be neutral, committed, anonymous, an instrument of the people, professional and impersonal. Each role has its own pressure point.',
 nodes=[
 OWN('I PANIC', 'Six roles, no sequence (handout order N-C-A-I-P-I): <b>I</b>mpersonality · <b>P</b>rofessionality · <b>A</b>nonymity · <b>N</b>eutrality · <b>I</b>nstrumentality · <b>C</b>ommitment. A good officer never says "I PANIC".'),
 hub('Civil servant in a democracy', ['Neutrality', 'Commitment', 'Anonymity', 'Instrumentality', 'Professionality', 'Impersonality']),
 sec('1 · NEUTRALITY ' + P('2017'), 'b'),
 t('<b>Three layers</b>', '<b>Class:</b> civil servants mostly come from the middle class, whose mindset often becomes the <b>dominant mindset of the bureaucracy</b>; <b>elite capture</b> of state institutions (example: National Rifle Association, USA) makes neutrality hard', '<b>Cultural:</b> neutrality on the basis of language, caste, religion, region and other social identities', '<b>Political:</b> neutral towards <b>all</b> political parties, expressed through <b>3 confidences</b> ↓', w=22),
 tb(['Confidence of', 'Meaning'], ['People', 'whichever party the people elect, civil services serve the elected government with <b>diligence, dedication and commitment</b>'], ['Ministers', 'irrespective of the ideology of the minister\'s party, civil servants perform duties with commitment'], ['Civil servants', 'decisions on <b>postings, careers and promotions</b> based on <b>objective merit and rationality</b>, not political affiliation']),
 bx('pk', '<b>Policy vs political neutrality:</b> ministers may lack specialised knowledge of policy and governance, so civil servants <b>advise</b> them on the right course. <b>Political neutrality ≠ policy neutrality:</b> an officer may prefer one policy over another while staying within <b>legality and constitutionality</b>. Involvement in policy = <b>purely intellectual, never emotional</b>. Civil servants <b>must understand politics, not play politics</b>, and must consider the <b>political implications</b> of policies they recommend.'),
 bx('ye', '<b>Problems:</b> a thinking person can never be completely neutral · the <b>4Cs</b> of the political environment (criminalisation, casteism, communalism, corruption) make neutrality difficult · parties may demand <b>loyalty</b> instead of encouraging neutrality · no complete agreement on fundamentals such as the country\'s vision and direction (extreme right, extreme left, secular parties) · rise of <b>multi-party democracy</b> exposes officers to pressure from different parties at Centre and state.'),
 tb(['Bhaskar Ghose\'s 3 types', 'Behaviour'], ['<b>Neither Wilt nor Tilt</b>', 'stand firm, refuse orders that deviate from established policy or law; may face transfers but do not compromise neutrality and honesty'], ['<b>Incorrigibly Corrupt</b>', 'find political godfathers early in their careers and align with political parties'], ['<b>Weather Report Readers</b>', 'shift loyalty with changing political circumstances; adjust positions to suit convenience']),
 sec('2-6 · THE OTHER FIVE', 'g'),
 t('<b>Commitment</b>', '<b>commitment towards:</b> impartial implementation of the rule of law; established code of ethics', 'settled policies; probity; transparency; duty', 'welfare of the <b>Daridra</b> (poorest of the poor)', w=24),
 t('<b>Anonymity</b>', 'works behind the scenes; <b>minister = public face</b>', 'credit for good goes to the minister; in a major failure the minister must also accept responsibility: anonymity goes <b>hand in hand with ministerial responsibility</b>', 'it is the <b>duty of ministers to protect civil servants</b>', '<span class="rd">changing</span> with social accountability mechanisms: social audits, RTI, Citizens\' Charters, time-bound public service delivery laws', w=24),
 t('<b>Instrumentality</b>', 'instrument of the people, but a full bureaucracy can become an <b>independent power structure</b> with elitist values', '<b>Max Weber:</b> once an institution, bureaucracy is among the hardest structures to dismantle', w=24),
 t('<b>Professionality</b>', 'a professional keeps improving knowledge and skills, stays updated, undertakes training; civil service is a profession', '<span class="rd">hindrances:</span> generalists in specialist services · poor training (largely Group A and B; only <b>1 in 5</b> can expect formal training; mid-career training absent or inadequate) · weak appraisal (no quantifiable targets) · weak incentives and disincentives: "<b>hire, but no fire</b>" · cadre-based dominance of IAS, limited lateral entry', w=24),
 t('<b>Impersonality</b>', 'don\'t personalise the post (DC, SP): impersonality = not personalising the position; the job is to discharge its duties faithfully', 'impersonal attitude to superiors, colleagues and juniors; over-personal ties dull objectivity (example: overlooking a friend\'s corruption)', w=24),
 sec('CIVIL SERVICES ACTIVISM', 'r'),
 bx('bl', '<b>Activism</b> = a civil servant takes the role of a <b>crusader</b> to address problems inside and outside government.'),
 t('<b>Forms</b>', 'going to the media; calculated leaks; going to courts', '<b>whistleblowing</b> = publicly exposing wrongdoing', '<b>grassroots activism</b> = initiatives that make people\'s interactions with district administration easier', '<b>post-retirement</b>: NGOs, civil society organisations, YouTube channels and similar platforms', w=22),
 bx('gr', '<b>Lakhina Experiment (Dr. Lakhina, IAS, Ahmednagar, 1980s):</b> officials needed older files but finding them in heaps was hard; he <b>colour-coded files by year</b>, making retrieval easy. Example of <b>grassroots activism</b>.'),
 t('<b>Issues</b>', 'may violate civil service rules and set a <b>bad precedent</b>', 'may <b>personalise institutional issues</b> (e.g. targeting the CM personally over corruption)', 'exposes civil services to manipulation by parties and media', 'can erode credibility of public and democratic institutions', w=22),
 bx('ye', '<b>Verdict:</b> activism as such <b>cannot be encouraged</b>, but it is a sign of our times. Civil service and electoral reforms, discussed for decades, must be implemented more effectively to ensure an appropriate political class and civil services.'),
 ],
 recall=[('Six roles', 'neutrality, commitment, anonymity, instrumentality, professionality, impersonality'), ('Three confidences', 'people, ministers, civil servants'), ('Ghose\'s 3 types', 'Wilt-Tilt (firm), Incorrigibly Corrupt, Weather Report Readers'), ('Training coverage', 'only 1 in 5 gets formal training'), ('Lakhina Experiment', 'colour-coded files by year, Ahmednagar 1980s')]),

